class Solution {
    int ans = 1e9;
    void backtrack(int idx, std::vector<int>& cookies, std::vector<int>& children, int k) {
        if (idx == (int)cookies.size()) {
            int cur = 0;
            for (int c : children) cur = std::max(cur, c);
            ans = std::min(ans, cur);
            return;
        }
        int curMax = 0;
        for (int c : children) curMax = std::max(curMax, c);
        if (curMax >= ans) return;
        for (int i = 0; i < k; ++i) {
            children[i] += cookies[idx];
            backtrack(idx + 1, cookies, children, k);
            children[i] -= cookies[idx];
            if (children[i] == 0) break;
        }
    }
public:
    int distributeCookies(std::vector<int>& cookies, int k) {
        std::sort(cookies.rbegin(), cookies.rend());
        std::vector<int> children(k, 0);
        ans = 1e9;
        backtrack(0, cookies, children, k);
        return ans;
    }
};

class Solution {
    private int ans = Integer.MAX_VALUE;
    public int distributeCookies(int[] cookies, int k) {
        java.util.Arrays.sort(cookies);
        for (int i = 0, j = cookies.length - 1; i < j; i++, j--) {
            int t = cookies[i]; cookies[i] = cookies[j]; cookies[j] = t;
        }
        int[] children = new int[k];
        ans = Integer.MAX_VALUE;
        backtrack(0, cookies, children, k);
        return ans;
    }
    private void backtrack(int idx, int[] cookies, int[] children, int k) {
        if (idx == cookies.length) {
            int cur = 0;
            for (int c : children) cur = Math.max(cur, c);
            ans = Math.min(ans, cur);
            return;
        }
        int curMax = 0;
        for (int c : children) curMax = Math.max(curMax, c);
        if (curMax >= ans) return;
        for (int i = 0; i < k; i++) {
            children[i] += cookies[idx];
            backtrack(idx + 1, cookies, children, k);
            children[i] -= cookies[idx];
            if (children[i] == 0) break;
        }
    }
}

var distributeCookies = function(cookies, k) {
    cookies.sort((a, b) => b - a);
    const children = new Int32Array(k);
    let ans = Infinity;
    const backtrack = (idx) => {
        if (idx === cookies.length) {
            let cur = 0;
            for (let i = 0; i < k; i++) if (children[i] > cur) cur = children[i];
            if (cur < ans) ans = cur;
            return;
        }
        let curMax = 0;
        for (let i = 0; i < k; i++) if (children[i] > curMax) curMax = children[i];
        if (curMax >= ans) return;
        for (let i = 0; i < k; i++) {
            children[i] += cookies[idx];
            backtrack(idx + 1);
            children[i] -= cookies[idx];
            if (children[i] === 0) break;
        }
    };
    backtrack(0);
    return ans;
};
